function makeId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}
function clean(value, fallback = "", limit = 1200) {
  if (typeof value !== "string") return fallback;
  const result = value.trim();
  return result ? result.slice(0, limit) : fallback;
}
function now() {
  return new Date().toISOString();
}
function emptyData() {
  return { releases: [], gates: [], decisions: [], risks: [], evidence: [], owners: [] };
}
function readData() {
  if (typeof window === "undefined") return emptyData();
  try {
    return { ...emptyData(), ...JSON.parse(window.localStorage.getItem(STORAGE_KEY) || "{}") };
  } catch {
    return emptyData();
  }
}
function tone(value) {
  if (["approved", "low"].includes(value)) return "emerald";
  if (["blocked", "critical", "high", "rejected"].includes(value)) return "rose";
  if (["in-review", "medium", "proposed"].includes(value)) return "amber";
  return "slate";
}
function Badge({ children, value }) {
  const colors = { slate: "border-slate-200 bg-slate-50 text-slate-700", emerald: "border-emerald-200 bg-emerald-50 text-emerald-800", amber: "border-amber-200 bg-amber-50 text-amber-800", rose: "border-rose-200 bg-rose-50 text-rose-800" };
  return <span className={`inline-flex rounded-full border px-2.5 py-1 text-[11px] font-semibold ${colors[tone(value)] || colors.slate}`}>{children}</span>;
}
function Button({ children, icon: Icon, onClick, variant = "secondary", type = "button" }) {
  const variants = { secondary: "border-slate-200 bg-white text-slate-700 hover:border-slate-300", primary: "border-violet-600 bg-violet-600 text-white hover:bg-violet-700", danger: "border-rose-200 bg-white text-rose-700 hover:bg-rose-50" };
  return <button type={type} onClick={onClick} className={`inline-flex h-9 items-center justify-center gap-2 rounded-lg border px-3 text-xs font-semibold ${variants[variant]}`}>{Icon && <Icon size={14} />}{children}</button>;
}
function Field({ label, value, onChange, placeholder, options, required = false }) {
  const common = { value: value || "", onChange: (event) => onChange(event.target.value), required, className: "mt-1.5 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm outline-none focus:border-violet-500" };
  return <label className="block text-xs font-semibold text-slate-700">{label}{options ? <select {...common}><option value="">Select...</option>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select> : <input {...common} placeholder={placeholder} />}</label>;
}
function Area({ label, value, onChange, placeholder }) {
  return <label className="block text-xs font-semibold text-slate-700">{label}<textarea value={value || ""} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} rows={4} className="mt-1.5 w-full resize-y rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-500" /></label>;
}
function Empty({ title, description, action }) {
  return <div className="p-8 text-center"><p className="text-sm font-semibold text-slate-800">{title}</p><p className="mx-auto mt-1 max-w-md text-xs text-slate-500">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function Section({ title, description, action, children }) {
  return <section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-start justify-between gap-3 border-b border-slate-100 p-5"><div><h2 className="text-sm font-semibold text-slate-950">{title}</h2><p className="mt-1 text-xs text-slate-500">{description}</p></div>{action}</div>{children}</section>;
}
function Modal({ title, onClose, children }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b p-5"><h2 className="font-semibold">{title}</h2><button type="button" onClick={onClose}><X size={17} /></button></div><div className="p-5">{children}</div></div></div>;
}
function Stat({ icon: Icon, label, value, detail }) {
  return <article className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-3xl font-semibold">{value}</p></div><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-violet-100 text-violet-700"><Icon size={17} /></span></div><p className="mt-2 text-[11px] text-slate-500">{detail}</p></article>;
}

export default function ReleaseApprovalPage() {
  const [data, setData] = useState(emptyData);
  const [selectedId, setSelectedId] = useState("");
  const [tab, setTab] = useState("overview");
  const [query, setQuery] = useState("");
  const [ascending, setAscending] = useState(false);
  const [modal, setModal] = useState("");
  const [notice, setNotice] = useState("");
  const [releaseForm, setReleaseForm] = useState({ title: "", version: "", owner: "", window: "", summary: "" });
  const [gateForm, setGateForm] = useState({ title: "", domain: "Functional", state: "planned", owner: "", evidence: "", due: "" });
  const [decisionForm, setDecisionForm] = useState({ title: "", state: "proposed", owner: "", rationale: "", review: "" });
  const [riskForm, setRiskForm] = useState({ title: "", level: "medium", owner: "", mitigation: "", expiry: "" });
  const [evidenceForm, setEvidenceForm] = useState({ title: "", kind: "Test result", reference: "", detail: "" });
  const [ownerForm, setOwnerForm] = useState({ name: "", role: "", area: "", availability: "available", backup: "" });

  useEffect(() => setData(readData()), []);
  useEffect(() => { if (typeof window !== "undefined") window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => { if (!notice) return undefined; const timer = window.setTimeout(() => setNotice(""), 2500); return () => window.clearTimeout(timer); }, [notice]);

  const release = data.releases.find((item) => item.id === selectedId);
  const gates = data.gates.filter((item) => !selectedId || item.releaseId === selectedId);
  const decisions = data.decisions.filter((item) => !selectedId || item.releaseId === selectedId);
  const risks = data.risks.filter((item) => !selectedId || item.releaseId === selectedId);
  const evidence = data.evidence.filter((item) => !selectedId || item.releaseId === selectedId);
  const owners = data.owners.filter((item) => !selectedId || item.releaseId === selectedId);
  const approved = gates.filter((item) => item.state === "approved").length;
  const blocked = gates.filter((item) => item.state === "blocked").length;
  const openRisks = risks.filter((item) => ["critical", "high", "medium"].includes(item.level));
  const score = gates.length ? Math.round((approved / gates.length) * 100) : 0;
  const filteredGates = useMemo(() => gates.filter((item) => `${item.title} ${item.domain} ${item.owner} ${item.evidence}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => { const result = a.title.localeCompare(b.title); return ascending ? result : result * -1; }), [ascending, gates, query]);

  function update(key, items) { setData((current) => ({ ...current, [key]: items })); }
  function addRelease(event) { event.preventDefault(); const item = { ...releaseForm, id: makeId("release"), title: clean(releaseForm.title), version: clean(releaseForm.version), owner: clean(releaseForm.owner), window: clean(releaseForm.window), summary: clean(releaseForm.summary), createdAt: now() }; update("releases", [item, ...data.releases]); setSelectedId(item.id); setReleaseForm({ title: "", version: "", owner: "", window: "", summary: "" }); setModal(""); setNotice("Release approval record created"); }
  function addGate(event) { event.preventDefault(); const item = { ...gateForm, id: makeId("gate"), releaseId: selectedId, title: clean(gateForm.title), owner: clean(gateForm.owner), evidence: clean(gateForm.evidence), due: clean(gateForm.due), createdAt: now() }; update("gates", [item, ...data.gates]); setGateForm({ title: "", domain: "Functional", state: "planned", owner: "", evidence: "", due: "" }); setModal(""); setNotice("Approval gate added"); }
  function addDecision(event) { event.preventDefault(); const item = { ...decisionForm, id: makeId("decision"), releaseId: selectedId, title: clean(decisionForm.title), owner: clean(decisionForm.owner), rationale: clean(decisionForm.rationale), review: clean(decisionForm.review), createdAt: now() }; update("decisions", [item, ...data.decisions]); setDecisionForm({ title: "", state: "proposed", owner: "", rationale: "", review: "" }); setModal(""); setNotice("Release decision added"); }
  function addRisk(event) { event.preventDefault(); const item = { ...riskForm, id: makeId("risk"), releaseId: selectedId, title: clean(riskForm.title), owner: clean(riskForm.owner), mitigation: clean(riskForm.mitigation), expiry: clean(riskForm.expiry), createdAt: now() }; update("risks", [item, ...data.risks]); setRiskForm({ title: "", level: "medium", owner: "", mitigation: "", expiry: "" }); setModal(""); setNotice("Release risk added"); }
  function addEvidence(event) { event.preventDefault(); const item = { ...evidenceForm, id: makeId("evidence"), releaseId: selectedId, title: clean(evidenceForm.title), reference: clean(evidenceForm.reference), detail: clean(evidenceForm.detail), createdAt: now() }; update("evidence", [item, ...data.evidence]); setEvidenceForm({ title: "", kind: "Test result", reference: "", detail: "" }); setModal(""); setNotice("Approval evidence added"); }
  function addOwner(event) { event.preventDefault(); const item = { ...ownerForm, id: makeId("owner"), releaseId: selectedId, name: clean(ownerForm.name), role: clean(ownerForm.role), area: clean(ownerForm.area), backup: clean(ownerForm.backup), createdAt: now() }; update("owners", [item, ...data.owners]); setOwnerForm({ name: "", role: "", area: "", availability: "available", backup: "" }); setModal(""); setNotice("Release owner added"); }
  function change(key, itemId, field, value) { update(key, data[key].map((item) => item.id === itemId ? { ...item, [field]: value, updatedAt: now() } : item)); }
  function remove(key, itemId) { update(key, data[key].filter((item) => item.id !== itemId)); setNotice("Record removed"); }
  function applyLibrary() { if (!selectedId) { setNotice("Select a release first"); return; } const items = APPROVAL_LIBRARY.slice(0, 30).map((title, index) => ({ id: makeId(`gate-${index}`), releaseId: selectedId, title, domain: DOMAINS[index % DOMAINS.length], state: "planned", owner: "", evidence: "", due: "", createdAt: now() })); update("gates", [...items, ...data.gates]); setNotice("Approval checklist applied"); }
  function copySummary() { navigator.clipboard?.writeText([`Release: ${release?.title || "All releases"}`, `Approval score: ${score}%`, `Approved gates: ${approved}/${gates.length}`, `Blocked gates: ${blocked}`, `Open risks: ${openRisks.length}`, `Decisions: ${decisions.length}`, `Evidence: ${evidence.length}`, `Owners: ${owners.length}`, release?.summary || "No summary recorded."].join("\n")); setNotice("Release summary copied"); }
  function exportRows() { const rows = [["Type", "Title", "Domain", "State", "Owner", "Detail"], ...gates.map((item) => ["Gate", item.title, item.domain, item.state, item.owner, item.evidence]), ...decisions.map((item) => ["Decision", item.title, "", item.state, item.owner, item.rationale]), ...risks.map((item) => ["Risk", item.title, "", item.level, item.owner, item.mitigation])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell || "").replaceAll('"', '""')}"`).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "release-approval.csv"; anchor.click(); URL.revokeObjectURL(url); setNotice("Approval export downloaded"); }

  const tabs = [["overview", "Overview"], ["gates", `Gates (${gates.length})`], ["decisions", `Decisions (${decisions.length})`], ["risks", `Risks (${risks.length})`], ["evidence", `Evidence (${evidence.length})`], ["owners", `Owners (${owners.length})`]];
  return <main className="min-h-screen bg-slate-50 px-4 py-8 text-slate-900 sm:px-8"><div className="mx-auto max-w-7xl space-y-5">
    <div className="rounded-3xl border border-violet-200 bg-gradient-to-br from-violet-50 via-white to-slate-50 p-5 shadow-sm sm:p-7"><div className="flex flex-col gap-5 lg:flex-row lg:justify-between"><div className="max-w-3xl"><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.16em] text-violet-700"><ShieldCheck size={16} /> Admin release approval</div><h1 className="mt-3 text-2xl font-semibold tracking-tight sm:text-3xl">Make release approval explicit, evidence-backed, and easy to hand off.</h1><p className="mt-3 text-sm leading-6 text-slate-600">A browser-local administration workspace for release gates, decisions, risks, evidence, ownership, and approval communication.</p></div><div className="flex flex-wrap gap-2"><Button icon={Plus} variant="primary" onClick={() => setModal("release")}>New release</Button><Button icon={Copy} onClick={copySummary}>Copy summary</Button><Button icon={Download} onClick={exportRows}>Export</Button></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Stat icon={Gauge} label="Approval score" value={`${score}%`} detail={`${approved} approved gates`} /><Stat icon={AlertTriangle} label="Blocked gates" value={blocked} detail={`${openRisks.length} open risks`} /><Stat icon={ClipboardCheck} label="Decisions" value={decisions.length} detail="Approval decisions" /><Stat icon={FileCheck2} label="Evidence" value={evidence.length} detail={`${owners.length} owners mapped`} /></div></div>
    {notice && <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs font-semibold text-emerald-800">{notice}</div>}
    <div className="flex flex-wrap gap-2 border-b border-slate-200 pb-1">{tabs.map(([value, label]) => <button key={value} type="button" onClick={() => setTab(value)} className={`rounded-t-lg px-3 py-2 text-xs font-semibold ${tab === value ? "border-b-2 border-violet-600 text-violet-700" : "text-slate-500"}`}>{label}</button>)}</div>
    <Section title="Release context" description="Select the release or create a new approval record." action={<Button icon={RefreshCw} onClick={() => { setData(readData()); setNotice("Approval workspace refreshed"); }}>Refresh</Button>}><div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1fr)_auto]"><label className="text-xs font-semibold text-slate-700">Selected release<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)} className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm"><option value="">All releases</option>{data.releases.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><div className="flex items-end gap-2"><Button icon={ClipboardCheck} onClick={applyLibrary}>Apply checklist</Button><Button icon={Plus} onClick={() => setModal("release")}>Add release</Button></div></div><div className="grid gap-3 border-t border-slate-100 p-5 md:grid-cols-2 xl:grid-cols-3">{data.releases.map((item) => <button key={item.id} type="button" onClick={() => setSelectedId(item.id)} className={`rounded-xl border p-4 text-left ${selectedId === item.id ? "border-violet-300 bg-violet-50" : "border-slate-200"}`}><div className="flex items-start justify-between gap-3"><p className="text-sm font-semibold">{item.title}</p><Badge value={item.version}>{item.version || "No version"}</Badge></div><p className="mt-2 line-clamp-2 text-xs text-slate-500">{item.summary || "No release summary recorded."}</p><p className="mt-3 text-[11px] text-slate-400">{item.window || "Window not set"} · {item.owner || "Unassigned"}</p></button>)}{!data.releases.length && <div className="md:col-span-2 xl:col-span-3"><Empty title="No release approval record" description="Create an approval record for a release, hotfix, migration, or rollback." action={<Button icon={Plus} variant="primary" onClick={() => setModal("release")}>Create release</Button>} /></div>}</div></Section>
    {tab === "overview" && <div className="grid gap-5 xl:grid-cols-2"><Section title="Approval posture" description="A quick read of release confidence and remaining attention."><div className="space-y-4 p-5"><div className="rounded-xl border border-violet-100 bg-violet-50 p-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-violet-900">Gate approval</p><p className="text-lg font-semibold text-violet-900">{score}%</p></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white"><div className="h-full rounded-full bg-violet-600" style={{ width: `${score}%` }} /></div><p className="mt-3 text-xs text-violet-800">{blocked ? `${blocked} blocked gate${blocked === 1 ? "" : "s"} need a decision.` : "No blocked gates recorded."}</p></div><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Gates</p><p className="mt-1 text-xl font-semibold">{gates.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Risks</p><p className="mt-1 text-xl font-semibold">{openRisks.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Owners</p><p className="mt-1 text-xl font-semibold">{owners.length}</p></div></div><p className="text-[11px] text-slate-500">Approval library: {APPROVAL_LIBRARY.length} reusable prompts. Audit library: {RELEASE_AUDIT_PROMPTS.length} additional checks across release readiness and handoff.</p></div></Section><Section title="Release narrative" description="Keep the approval reasoning close to the measurable signals."><div className="space-y-4 p-5"><Area label="Summary" value={release?.summary || ""} onChange={(value) => release && change("releases", release.id, "summary", value)} placeholder="What is being released and what outcome is expected?" /><Area label="Recommendation" value={release?.recommendation || ""} onChange={(value) => release && change("releases", release.id, "recommendation", value)} placeholder="What should the approver decide and why?" /></div></Section><Section title="Approval principles" description="Use consistent rules for release decisions."><div className="grid gap-3 p-5 sm:grid-cols-2">{[["Evidence first", "A gate should point to proof, not only an assertion.", FileCheck2], ["Risk visible", "Open risks need owners, mitigation, and expiry.", AlertTriangle], ["Decision explicit", "Record approval, rejection, deferral, or waiver.", CheckCircle2], ["Handoff ready", "Make the next owner and next check visible.", Users]].map(([title, detail, Icon]) => <div key={title} className="rounded-xl border border-slate-200 p-4"><Icon size={17} className="text-violet-600" /><p className="mt-3 text-sm font-semibold">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{detail}</p></div>)}</div></Section><Section title="Approval prompts" description="Load a reusable prompt into a new gate."><div className="grid gap-2 p-5 sm:grid-cols-2">{APPROVAL_LIBRARY.slice(0, 12).map((prompt) => <button key={prompt} type="button" onClick={() => { setTab("gates"); setGateForm((current) => ({ ...current, title: prompt })); setNotice("Prompt loaded into gate form"); }} className="rounded-lg border border-slate-200 px-3 py-2 text-left text-[11px] text-slate-600 hover:border-violet-300 hover:text-violet-700">{prompt}</button>)}</div></Section></div>}
    {tab === "gates" && <Section title="Approval gates" description="Track release criteria, evidence, owners, and state." action={<Button icon={Plus} variant="primary" onClick={() => setModal("gate")}>Add gate</Button>}><div className="flex gap-3 border-b border-slate-100 p-5"><div className="relative min-w-0 flex-1"><Search size={15} className="absolute left-3 top-3 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search gates, domains, owners..." className="h-10 w-full rounded-lg border border-slate-200 pl-9 pr-3 text-sm" /></div><Button icon={ascending ? ArrowUpAZ : ArrowDownAZ} onClick={() => setAscending((value) => !value)}>Sort</Button></div>{!filteredGates.length ? <Empty title="No approval gates" description="Apply the checklist or add a targeted release gate." action={<Button icon={ClipboardCheck} onClick={applyLibrary}>Apply checklist</Button>} /> : <div className="divide-y">{filteredGates.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold">{item.title}</h3><Badge value={item.state}>{item.state}</Badge><Badge value={item.domain}>{item.domain}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.evidence || "No evidence requirement recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Due: {item.due || "Not set"}</p></div><div className="flex gap-2"><select value={item.state} onChange={(event) => change("gates", item.id, "state", event.target.value)} className="h-8 rounded-lg border border-slate-200 px-2 text-[11px]">{GATE_STATES.map((state) => <option key={state} value={state}>{state}</option>)}</select><Button variant="danger" icon={Trash2} onClick={() => remove("gates", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    {tab === "decisions" && <Section title="Approval decisions" description="Record the decision, rationale, owner, and review point." action={<Button icon={Plus} variant="primary" onClick={() => setModal("decision")}>Add decision</Button>}>{!decisions.length ? <Empty title="No release decisions" description="Record an approval, rejection, deferral, or waiver." action={<Button icon={Plus} onClick={() => setModal("decision")}>Add decision</Button>} /> : <div className="divide-y">{decisions.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:justify-between"><div><div className="flex flex-wrap gap-2"><h3 className="text-sm font-semibold">{item.title}</h3><Badge value={item.state}>{item.state}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.rationale || "No rationale recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Review: {item.review || "Not set"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("decisions", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "risks" && <Section title="Release risks and exceptions" description="Track unresolved concerns and accepted exceptions." action={<Button icon={Plus} variant="primary" onClick={() => setModal("risk")}>Add risk</Button>}>{!risks.length ? <Empty title="No release risks" description="Add an unresolved risk, waiver, or exception." action={<Button icon={Plus} onClick={() => setModal("risk")}>Add risk</Button>} /> : <div className="divide-y">{risks.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:justify-between"><div><div className="flex flex-wrap gap-2"><h3 className="text-sm font-semibold">{item.title}</h3><Badge value={item.level}>{item.level}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.mitigation || "No mitigation recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Expiry: {item.expiry || "Not set"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("risks", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "evidence" && <Section title="Approval evidence" description="Index proof for gates, decisions, risks, and handoff." action={<Button icon={Plus} variant="primary" onClick={() => setModal("evidence")}>Add evidence</Button>}>{!evidence.length ? <Empty title="No approval evidence" description="Add test results, logs, screenshots, links, or decision notes." action={<Button icon={Plus} onClick={() => setModal("evidence")}>Add evidence</Button>} /> : <div className="divide-y">{evidence.map((item) => <div key={item.id} className="flex justify-between gap-3 p-5"><div><div className="flex flex-wrap gap-2"><h3 className="text-sm font-semibold">{item.title}</h3><Badge value={item.kind}>{item.kind}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || "No detail recorded."}</p><p className="mt-2 text-[11px] text-violet-700">{item.reference || "No reference recorded"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("evidence", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "owners" && <Section title="Approval ownership" description="Map approvers, release owners, backups, and domain leads." action={<Button icon={Plus} variant="primary" onClick={() => setModal("owner")}>Add owner</Button>}>{!owners.length ? <Empty title="No approval owners" description="Add owners for release, quality, security, operations, and support." action={<Button icon={Plus} onClick={() => setModal("owner")}>Add owner</Button>} /> : <div className="grid gap-3 p-5 md:grid-cols-2">{owners.map((item) => <div key={item.id} className="rounded-xl border border-slate-200 p-4"><div className="flex justify-between gap-3"><div><p className="text-sm font-semibold">{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.role} · {item.area}</p></div><Badge value={item.availability}>{item.availability}</Badge></div><p className="mt-3 text-[11px] text-slate-500">Backup: {item.backup || "Not assigned"}</p><div className="mt-3"><Button variant="danger" icon={Trash2} onClick={() => remove("owners", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    <Section title="Approval prompt library" description="Reusable review prompts remain local to this browser."><div className="grid gap-2 p-5 sm:grid-cols-2 lg:grid-cols-3">{APPROVAL_LIBRARY.slice(0, 18).map((prompt) => <button key={prompt} type="button" onClick={() => { setTab("gates"); setGateForm((current) => ({ ...current, title: prompt })); setNotice("Prompt loaded into gate form"); }} className="rounded-lg border border-slate-200 px-3 py-2 text-left text-[11px] text-slate-600 hover:border-violet-300 hover:text-violet-700">{prompt}</button>)}</div><p className="px-5 pb-5 text-[11px] text-slate-400">The full library contains {APPROVAL_LIBRARY.length} reusable approval prompts.</p></Section>
    <Section title="Release audit prompt library" description="Use additional prompts to prepare approval meetings and handoffs."><div className="grid gap-2 p-5 sm:grid-cols-2 lg:grid-cols-3">{RELEASE_AUDIT_PROMPTS.slice(0, 18).map((prompt) => <button key={prompt} type="button" onClick={() => { setTab("gates"); setGateForm((current) => ({ ...current, title: prompt })); setNotice("Audit prompt loaded into gate form"); }} className="rounded-lg border border-slate-200 px-3 py-2 text-left text-[11px] text-slate-600 hover:border-violet-300 hover:text-violet-700">{prompt}</button>)}</div><p className="px-5 pb-5 text-[11px] text-slate-400">The audit library contains {RELEASE_AUDIT_PROMPTS.length} additional prompts.</p></Section>
    {modal === "release" && <Modal title="Create release approval" onClose={() => setModal("")}><form onSubmit={addRelease} className="space-y-4"><Field label="Release title" value={releaseForm.title} onChange={(value) => setReleaseForm({ ...releaseForm, title: value })} placeholder="Release 2.5 approval" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Version" value={releaseForm.version} onChange={(value) => setReleaseForm({ ...releaseForm, version: value })} placeholder="2.5.0" /><Field label="Window" value={releaseForm.window} onChange={(value) => setReleaseForm({ ...releaseForm, window: value })} placeholder="Friday 20:00 UTC" /><Field label="Owner" value={releaseForm.owner} onChange={(value) => setReleaseForm({ ...releaseForm, owner: value })} placeholder="Release manager" /></div><Area label="Summary" value={releaseForm.summary} onChange={(value) => setReleaseForm({ ...releaseForm, summary: value })} placeholder="What is included and what decision is needed?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Create release</Button></div></form></Modal>}
    {modal === "gate" && <Modal title="Add approval gate" onClose={() => setModal("")}><form onSubmit={addGate} className="space-y-4"><Field label="Gate title" value={gateForm.title} onChange={(value) => setGateForm({ ...gateForm, title: value })} placeholder="Rollback procedure is tested" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Domain" options={DOMAINS} value={gateForm.domain} onChange={(value) => setGateForm({ ...gateForm, domain: value })} /><Field label="State" options={GATE_STATES} value={gateForm.state} onChange={(value) => setGateForm({ ...gateForm, state: value })} /><Field label="Owner" value={gateForm.owner} onChange={(value) => setGateForm({ ...gateForm, owner: value })} /><Field label="Due" value={gateForm.due} onChange={(value) => setGateForm({ ...gateForm, due: value })} placeholder="Before approval" /></div><Area label="Evidence" value={gateForm.evidence} onChange={(value) => setGateForm({ ...gateForm, evidence: value })} placeholder="What proves this gate is ready?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add gate</Button></div></form></Modal>}
    {modal === "decision" && <Modal title="Record approval decision" onClose={() => setModal("")}><form onSubmit={addDecision} className="space-y-4"><Field label="Decision title" value={decisionForm.title} onChange={(value) => setDecisionForm({ ...decisionForm, title: value })} placeholder="Approve release with monitoring exception" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="State" options={DECISION_STATES} value={decisionForm.state} onChange={(value) => setDecisionForm({ ...decisionForm, state: value })} /><Field label="Owner" value={decisionForm.owner} onChange={(value) => setDecisionForm({ ...decisionForm, owner: value })} /><Field label="Review" value={decisionForm.review} onChange={(value) => setDecisionForm({ ...decisionForm, review: value })} placeholder="After release" /></div><Area label="Rationale" value={decisionForm.rationale} onChange={(value) => setDecisionForm({ ...decisionForm, rationale: value })} placeholder="Evidence, trade-offs, conditions, and follow-up." /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Record decision</Button></div></form></Modal>}
    {modal === "risk" && <Modal title="Add release risk" onClose={() => setModal("")}><form onSubmit={addRisk} className="space-y-4"><Field label="Risk title" value={riskForm.title} onChange={(value) => setRiskForm({ ...riskForm, title: value })} placeholder="Mobile verification is incomplete" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Level" options={LEVELS} value={riskForm.level} onChange={(value) => setRiskForm({ ...riskForm, level: value })} /><Field label="Owner" value={riskForm.owner} onChange={(value) => setRiskForm({ ...riskForm, owner: value })} /><Field label="Expiry" value={riskForm.expiry} onChange={(value) => setRiskForm({ ...riskForm, expiry: value })} placeholder="Next release" /></div><Area label="Mitigation" value={riskForm.mitigation} onChange={(value) => setRiskForm({ ...riskForm, mitigation: value })} placeholder="What reduces this risk?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add risk</Button></div></form></Modal>}
    {modal === "evidence" && <Modal title="Add approval evidence" onClose={() => setModal("")}><form onSubmit={addEvidence} className="space-y-4"><Field label="Evidence title" value={evidenceForm.title} onChange={(value) => setEvidenceForm({ ...evidenceForm, title: value })} placeholder="Production smoke results" required /><Field label="Kind" options={["Test result", "Screenshot", "Recording", "Log", "Report", "Link", "Decision note"]} value={evidenceForm.kind} onChange={(value) => setEvidenceForm({ ...evidenceForm, kind: value })} /><Field label="Reference" value={evidenceForm.reference} onChange={(value) => setEvidenceForm({ ...evidenceForm, reference: value })} placeholder="URL, report id, or file name" /><Area label="Detail" value={evidenceForm.detail} onChange={(value) => setEvidenceForm({ ...evidenceForm, detail: value })} placeholder="What does this prove?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add evidence</Button></div></form></Modal>}
    {modal === "owner" && <Modal title="Add approval owner" onClose={() => setModal("")}><form onSubmit={addOwner} className="space-y-4"><Field label="Name" value={ownerForm.name} onChange={(value) => setOwnerForm({ ...ownerForm, name: value })} placeholder="Approver name" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Role" value={ownerForm.role} onChange={(value) => setOwnerForm({ ...ownerForm, role: value })} placeholder="Release manager" /><Field label="Area" value={ownerForm.area} onChange={(value) => setOwnerForm({ ...ownerForm, area: value })} placeholder="Operations" /><Field label="Availability" options={["available", "busy", "offline", "unknown"]} value={ownerForm.availability} onChange={(value) => setOwnerForm({ ...ownerForm, availability: value })} /><Field label="Backup" value={ownerForm.backup} onChange={(value) => setOwnerForm({ ...ownerForm, backup: value })} placeholder="Backup owner" /></div><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add owner</Button></div></form></Modal>}
  </div></main>;
}
